using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorProjectFilePickerOperations:RefCounted
{
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private static bool Bool(Node owner,string key)=>owner.Get(key).AsBool();private static string Text(Node owner,string key)=>owner.Get(key).AsString();
    internal static bool Inside(string root,string path){root=root.Replace('\\','/');path=path.Replace('\\','/');return root==path||path.SimplifyPath().StartsWith(root.SimplifyPath().TrimEnd('/')+"/",StringComparison.Ordinal);}
    internal static Texture2D FileIcon=>GD.Load<Texture2D>("uid://mwmlqweqemfk");internal static Texture2D FolderIcon=>GD.Load<Texture2D>("uid://h5xgw3ns54ys");
    private static GodotObject? Library(Node owner)=>owner.Call("_clipboard_library").AsGodotObject();
    private static GodotObject Store(GodotObject library)=>library.Get("store").AsGodotObject();
    public string root_directory(){var project=StaticData.get_loaded_project();return project!=null&&project.ResourcePath.Length>0?GD.Load<GDScript>("res://scripts/Globals/local_project_filesystem.gd").Call("get_project_root_directory").AsString().SimplifyPath():ProjectSettings.GlobalizePath("res://").SimplifyPath();}
    public bool is_allowed_path(string root,string path,string[] extensions){root=root.SimplifyPath();path=path.SimplifyPath();return Inside(root,path)&&Godot.FileAccess.FileExists(path)&&(extensions.Length==0||Array.IndexOf(extensions,path.GetExtension().ToLowerInvariant())>=0);}
    public string relative_to_project(Node owner,string path){string root=Text(owner,"project_root").Replace('\\','/').SimplifyPath().TrimEnd('/'),normalized=path.Replace('\\','/').SimplifyPath();return normalized==root?".":normalized.StartsWith(root+"/",StringComparison.Ordinal)?normalized.Substring(root.Length+1):normalized;}
    public string godot_resource_path(string path){if(path.StartsWith("res://",StringComparison.Ordinal)||path.StartsWith("user://",StringComparison.Ordinal))return path;string root=ProjectSettings.GlobalizePath("res://").Replace('\\','/').TrimEnd('/'),normalized=path.Replace('\\','/');return normalized.StartsWith(root+"/",StringComparison.Ordinal)?"res://"+normalized.Substring(root.Length+1):path;}
    public bool path_allowed(Node owner,string path){var cache=owner.Get("_path_match_cache").AsGodotDictionary();if(cache.TryGetValue(path,out var value))return value.AsBool();bool result=path_allowed_uncached(owner,path);cache[path]=result;return result;}
    public bool path_allowed_uncached(Node owner,string path)
    {
        var library=Library(owner);bool clipboard=Bool(owner,"clipboard_source");string scope=clipboard&&library!=null?Store(library).Get("root").AsString():Text(owner,"project_root");if(!is_allowed_path(scope,path,owner.Get("allowed_extensions").AsStringArray()))return false;if(clipboard&&!GD.Load<GDScript>("res://scripts/clipboard/clipboard_snapshot.gd").Call("safe_resource",path).AsBool())return false;var native=owner.Get("allowed_native_types").AsStringArray();string extension=path.GetExtension().ToLowerInvariant();if(extension=="tres"&&native.Length==1&&native[0]=="KiwiImageDocument"){using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);return file!=null&&file.GetLine().Contains("script_class=\"KiwiImageDocument\"",StringComparison.Ordinal);}
        string type=Text(owner,"allowed_resource_type");var accepted=owner.Get("accepted_object_types").AsStringArray();if(native.Length>0&&(extension is "tres" or "res" or "mesh")){var resource=ResourceLoader.Load(godot_resource_path(path),"",ResourceLoader.CacheMode.Ignore);foreach(string target in native)if(Matches(resource,target))return true;return ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd")&&type.Length>0&&Array.IndexOf(accepted,resource.Get("type_id").AsString())>=0;}if(type.Length==0||Array.IndexOf(owner.Get("allowed_raw_extensions").AsStringArray(),extension)>=0)return true;var loaded=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);return ActorDataOperations.ScriptIs(loaded,"res://scripts/actors/core/actor_object_data.gd")&&Array.IndexOf(accepted,loaded.Get("type_id").AsString())>=0;
    }
    private static bool Matches(Resource? resource,string type)
    {
        if(resource==null)return false;return type switch{"Environment"=>resource is Godot.Environment,"Mesh"=>resource is Mesh,"PackedScene"=>resource is PackedScene,"Texture2D"=>resource is Texture2D,"Material"=>resource is Material,"ActorSceneData"=>ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_scene_data.gd"),"KiwiImageDocument"=>ActorDataOperations.ScriptIs(resource,"res://Workspaces/ImageWorkspace/image_document.gd"),"KiwiTransformationImage2D"=>ActorDataOperations.ScriptIs(resource,"res://Workspaces/TransformationWorkspace/transformation_document.gd"),"KiwiModelDocument"=>ActorDataOperations.ScriptIs(resource,"res://Workspaces/ModelWorkspace/model_document.gd"),"KiwiEnvironmentDocument"=>ActorDataOperations.ScriptIs(resource,"res://Workspaces/EnvironmentWorkspace/environment_document.gd"),"KiwiImagePatternPreset"=>ActorDataOperations.ScriptIs(resource,"res://Workspaces/ImageWorkspace/image_pattern_preset.gd"),"KiwiRigPreset"=>GD.Load<GDScript>("res://Workspaces/ModelWorkspace/rig/rig_preset.gd").Call("accepts",resource).AsBool(),_=>false};
    }
    public void populate_tree(Node owner,TreeItem parent,Settings scan)
    {
        var tree=owner.Get("folders").As<Tree>();foreach(var value in scan["folders"].AsGodotArray()){var child=value.AsGodotDictionary();string path=child["path"].AsString();var item=tree.CreateItem(parent);item.SetText(0,path.GetFile()+"  ("+child["count"].AsInt32()+")");item.SetIcon(0,FolderIcon);item.SetIconMaxWidth(0,18);item.SetMetadata(0,path);item.SetMeta("is_file",false);populate_tree(owner,item,child);}foreach(var value in scan["files"].AsGodotArray()){string path=value.AsString();var item=tree.CreateItem(parent);item.SetText(0,path.GetFile());item.SetIcon(0,FileIcon);item.SetIconMaxWidth(0,20);item.SetMetadata(0,path);item.SetMeta("is_file",true);load_tree_thumbnail(owner,path,item,owner.Get("_tree_generation").AsInt32());}
    }
    public void tree_item_selected(Node owner)
    {
        var item=owner.Get("folders").As<Tree>().GetSelected();if(item==null)return;if(Bool(owner,"clipboard_source")){owner.Set("clipboard_folder",item.GetMetadata(0).AsString());refresh_files(owner);return;}string path=item.GetMetadata(0).AsString().SimplifyPath();if(item.GetMeta("is_file",false).AsBool()){select_asset(owner,path,item.GetIcon(0));var files=owner.Get("files").As<ItemList>();for(int index=0;index<files.ItemCount;index++)if(files.GetItemMetadata(index).AsString()==path){files.Select(index);files.EnsureCurrentIsVisible();break;}return;}if(!Inside(Text(owner,"project_root"),path)||!DirAccess.DirExistsAbsolute(path))return;owner.Set("current_directory",path);var search=owner.Get("search").As<LineEdit>();if(search.Text.Length==0)refresh_files(owner);else search.Text="";
    }
    public void tree_item_activated(Node owner){var item=owner.Get("folders").As<Tree>().GetSelected();if(item!=null&&item.GetMeta("is_file",false).AsBool())choose(owner);}
    public void refresh_files(Node owner)
    {
        if(Bool(owner,"clipboard_source")){refresh_clipboard_files(owner);return;}var files=owner.Get("files").As<ItemList>();if(files==null||!Bool(owner,"_scan_ready")||Bool(owner,"_resolved"))return;int generation=owner.Get("_refresh_generation").AsInt32()+1;owner.Set("_refresh_generation",generation);files.Clear();owner.Set("selected_path","");owner.Get("choose_button").As<Button>().Disabled=true;owner.Get("selection_preview").As<TextureRect>().Texture=FileIcon;owner.Get("selection_name").As<Label>().Text="No asset selected";owner.Get("selection_path").As<Label>().Text="Choose a matching file from the project";string query=owner.Get("search").As<LineEdit>().Text.Trim().ToLowerInvariant();var paths=new List<string>();foreach(var value in owner.Get("_indexed_paths").AsGodotArray()){string path=value.AsString();if(query.Length==0?Inside(Text(owner,"current_directory"),path):path.GetFile().ToLowerInvariant().Contains(query))paths.Add(path);}paths.Sort(StringComparer.Ordinal);foreach(string path in paths){string display=path.GetFile(),relative=relative_to_project(owner,path).GetBaseDir();if(relative!=".")display+="\n"+relative;int index=files.AddItem(display,FileIcon);files.SetItemMetadata(index,path);load_thumbnail(owner,path,index,generation);}owner.Get("breadcrumb").As<Label>().Text=Text(owner,"current_directory")==Text(owner,"project_root")?"Project":"Project  /  "+relative_to_project(owner,Text(owner,"current_directory")).Replace("/","  /  ");owner.Get("file_count").As<Label>().Text=paths.Count+" matching file"+(paths.Count==1?"":"s");if(paths.Count==0){files.AddItem("No matching files in this folder");files.SetItemDisabled(0,true);}
    }
    public void collect_files(Node owner,string directory,GArray result,bool recursive,string query){foreach(string name in DirAccess.GetFilesAt(directory)){string path=directory.PathJoin(name).SimplifyPath();if(path_allowed(owner,path)&&(query.Length==0||name.ToLowerInvariant().Contains(query)))result.Add(path);}if(recursive)foreach(string name in DirAccess.GetDirectoriesAt(directory))if(!name.StartsWith(".",StringComparison.Ordinal))collect_files(owner,directory.PathJoin(name),result,true,query);}
    public void load_thumbnail(Node owner,string path,int index,int generation)=>owner.Get("_thumbnail_jobs").AsGodotArray().Add(new Settings{["path"]=path,["index"]=index,["generation"]=generation});
    public void load_tree_thumbnail(Node owner,string path,TreeItem item,int generation)=>owner.Get("_thumbnail_jobs").AsGodotArray().Add(new Settings{["path"]=path,["item"]=item,["generation"]=generation});
    public void process(Node owner){var jobs=owner.Get("_thumbnail_jobs").AsGodotArray();if(Bool(owner,"_resolved")||Bool(owner,"_thumbnail_running")||jobs.Count==0)return;owner.Set("_thumbnail_running",true);var job=jobs[0];jobs.RemoveAt(0);owner.Call("_process_thumbnail",job);}
    public Texture2D? thumbnail_complete(Node owner,Settings job,Texture2D? texture)
    {
        string path=job["path"].AsString();if(texture!=null&&Math.Max(texture.GetWidth(),texture.GetHeight())>192){using var image=texture.GetImage();if(image!=null){double ratio=192.0/Math.Max(image.GetWidth(),image.GetHeight());image.Resize(Math.Max(1,(int)Math.Round(image.GetWidth()*ratio,MidpointRounding.AwayFromZero)),Math.Max(1,(int)Math.Round(image.GetHeight()*ratio,MidpointRounding.AwayFromZero)),Image.Interpolation.Bilinear);texture=ImageTexture.CreateFromImage(image);}}if(texture!=null)owner.Get("_thumbnail_cache").AsGodotDictionary()[path]=texture;owner.Set("_thumbnail_running",false);if(Bool(owner,"_resolved")||texture==null)return texture;int generation=job["generation"].AsInt32();if(job.ContainsKey("item")){var item=job["item"].AsGodotObject();if(generation==owner.Get("_tree_generation").AsInt32()&&GodotObject.IsInstanceValid(item)&&item is TreeItem treeItem)treeItem.SetIcon(0,texture);}else{var files=owner.Get("files").As<ItemList>();int index=job["index"].AsInt32();if(generation==owner.Get("_refresh_generation").AsInt32()&&GodotObject.IsInstanceValid(files)&&index>=0&&index<files.ItemCount&&files.GetItemMetadata(index).AsString()==path){files.SetItemIcon(index,texture);if(path==Text(owner,"selected_path"))owner.Get("selection_preview").As<TextureRect>().Texture=texture;}}return texture;
    }
    public void file_selected(Node owner,int index){var files=owner.Get("files").As<ItemList>();if(index>=0&&index<files.ItemCount&&!files.IsItemDisabled(index))select_asset(owner,files.GetItemMetadata(index).AsString().SimplifyPath(),files.GetItemIcon(index));}
    public void select_asset(Node owner,string path,Texture2D? preview){owner.Set("selected_path",path);owner.Get("choose_button").As<Button>().Disabled=!path_allowed(owner,path);owner.Get("selection_name").As<Label>().Text=path.GetFile();var label=owner.Get("selection_path").As<Label>();label.Text=relative_to_project(owner,path);label.TooltipText=path;owner.Get("selection_preview").As<TextureRect>().Texture=preview;}
    public void choose(Node owner){string path=Text(owner,"selected_path");if(!path_allowed(owner,path))return;if(Bool(owner,"clipboard_source")){var library=Library(owner);if(library==null)return;path=library.Call("import_item",Get(owner.Get("_clipboard_ids").AsGodotDictionary(),path,"").AsString()).AsString();if(path.Length>0)resolve(owner,path);else owner.Get("selection_path").As<Label>().Text=Store(library).Get("error").AsString();}else resolve(owner,path);}
    public void clipboard_folders(Node owner,TreeItem parent,string id,Settings visited){if(visited.ContainsKey(id))return;visited[id]=true;var library=Library(owner);if(library==null)return;var folders=Store(library).Get("data").AsGodotDictionary()["folders"].AsGodotDictionary();foreach(var key in folders.Keys){var entry=folders[key].AsGodotDictionary();if(Get(entry,"deleted",false).AsBool()||entry["parent"].AsString()!=id)continue;var row=owner.Get("folders").As<Tree>().CreateItem(parent);row.SetText(0,entry["name"].AsString());row.SetMetadata(0,key);row.SetIcon(0,FolderIcon);row.SetIconMaxWidth(0,18);clipboard_folders(owner,row,key.AsString(),visited);}}
    public bool clipboard_compatible(Node owner,Settings entry){string extension=Get(entry,"extension","").AsString();var extensions=owner.Get("allowed_extensions").AsStringArray();if(extensions.Length>0&&Array.IndexOf(extensions,extension)<0)return false;if(Array.IndexOf(owner.Get("allowed_raw_extensions").AsStringArray(),extension)>=0)return true;string type=Text(owner,"allowed_resource_type");var native=owner.Get("allowed_native_types").AsStringArray();if(type.Length==0&&native.Length==0)return true;if(type.Length>0&&Array.IndexOf(owner.Get("accepted_object_types").AsStringArray(),Get(entry,"object_type","").AsString())>=0)return true;var types=Get(entry,"native_types",new GArray()).AsGodotArray();return native.Any(value=>types.Contains(value));}
    public void refresh_clipboard_files(Node owner)
    {
        var files=owner.Get("files").As<ItemList>();if(files==null)return;owner.Set("_refresh_generation",owner.Get("_refresh_generation").AsInt32()+1);files.Clear();var ids=owner.Get("_clipboard_ids").AsGodotDictionary();ids.Clear();owner.Set("selected_path","");owner.Get("choose_button").As<Button>().Disabled=true;var library=Library(owner);if(library==null)return;var store=Store(library);var data=store.Get("data").AsGodotDictionary();string query=owner.Get("search").As<LineEdit>().Text.Trim().ToLowerInvariant();var entries=data["entries"].AsGodotDictionary();foreach(var id in entries.Keys){var entry=entries[id].AsGodotDictionary();if(Get(entry,"deleted",false).AsBool()||query.Length==0&&entry["folder"].AsString()!=Text(owner,"clipboard_folder"))continue;if(query.Length>0&&!(entry["name"].AsString()+" "+entry["type"].AsString()).ToLowerInvariant().Contains(query))continue;string path=store.Call("entry_path",id).AsString();if(path.Length==0||!clipboard_compatible(owner,entry))continue;ids[path]=id;int index=files.AddItem(entry["name"].AsString(),store.Call("icon",id).As<Texture2D>());files.SetItemMetadata(index,path);}var folder=Get(data["folders"].AsGodotDictionary(),Text(owner,"clipboard_folder"),new Settings()).AsGodotDictionary();owner.Get("breadcrumb").As<Label>().Text="Super Clipboard / "+Get(folder,"name","Default").AsString();owner.Get("file_count").As<Label>().Text=files.ItemCount+" compatible resources";
    }
    public void set_clipboard_source(Node owner,bool enabled){owner.Set("clipboard_source",enabled);owner.Get("source_project").As<Button>().SetPressedNoSignal(!enabled);owner.Get("source_clipboard").As<Button>().SetPressedNoSignal(enabled);owner.Set("_tree_generation",owner.Get("_tree_generation").AsInt32()+1);owner.Set("_refresh_generation",owner.Get("_refresh_generation").AsInt32()+1);owner.Get("_path_match_cache").AsGodotDictionary().Clear();owner.Get("_thumbnail_jobs").AsGodotArray().Clear();owner.Set("selected_path","");owner.Get("choose_button").As<Button>().Disabled=true;owner.Get("search").As<LineEdit>().Editable=true;if(!enabled){owner.Get("_indexed_paths").AsGodotArray().Clear();owner.Set("_scan_ready",false);owner.Set("current_directory",owner.Get("project_root"));owner.Call("_rebuild_folders");return;}var tree=owner.Get("folders").As<Tree>();tree.Clear();var root=tree.CreateItem();root.SetText(0,"Super Clipboard");root.SetMetadata(0,"default");clipboard_folders(owner,root,"",new Settings());refresh_clipboard_files(owner);}
    public void choose_default_slot(Node owner){var library=Library(owner);if(library==null)return;set_clipboard_source(owner,true);string id=Store(library).Get("data").AsGodotDictionary()["default_slot"].AsString(),path=Store(library).Call("entry_path",id).AsString();if(path.Length==0||!path_allowed(owner,path)){owner.Get("selection_name").As<Label>().Text="Default Slot is empty or incompatible";return;}owner.Get("_clipboard_ids").AsGodotDictionary()[path]=id;owner.Set("selected_path",path);choose(owner);}
    public void resolve(Node owner,string path){if(Bool(owner,"_resolved"))return;owner.Set("_resolved",true);owner.Get("_thumbnail_jobs").AsGodotArray().Clear();owner.EmitSignal("finished",path);((PopupPanel)owner).Hide();}
    public StyleBoxFlat box(Color background,Color border,int radius,int width){var style=new StyleBoxFlat{BgColor=background,BorderColor=border};style.SetBorderWidthAll(width);style.SetCornerRadiusAll(radius);return style;}
